import React, { useState } from 'react';
import { FiSearch, FiEye, FiCheckCircle, FiXCircle, FiClock } from 'react-icons/fi';
import './dashboard.css';

const JobsManagement = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState('all');

  const jobs = [
    { id: 1, title: 'Senior React Developer', company: 'Tech Startup Inc', salary: '$5000-7000', applications: 28, status: 'active', posted: '2d', views: 450 },
    { id: 2, title: 'UI/UX Designer', company: 'Design Studios', salary: '$3500-5000', applications: 15, status: 'active', posted: '5d', views: 320 },
    { id: 3, title: 'Full Stack Developer', company: 'Web Solutions', salary: '$6000-8000', applications: 22, status: 'active', posted: '1wk', views: 380 },
    { id: 4, title: 'Data Scientist', company: 'AI Company', salary: '$7000-9000', applications: 18, status: 'closed', posted: '1wk', views: 290 },
    { id: 5, title: 'Content Writer', company: 'Marketing Pro', salary: '$1500-2500', applications: 35, status: 'active', posted: '3d', views: 520 },
    { id: 6, title: 'Mobile App Developer', company: 'App Labs', salary: '$5000-7500', applications: 12, status: 'pending', posted: '6h', views: 85 },
  ];

  const filteredJobs = jobs.filter(j => {
    const matchesSearch = j.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         j.company.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesFilter = filter === 'all' || j.status === filter;
    return matchesSearch && matchesFilter;
  });

  const getStatusBadge = (status) => {
    const styles = {
      active: { bg: '#00d973', icon: FiCheckCircle, text: 'Active' },
      closed: { bg: '#ff6b6b', icon: FiXCircle, text: 'Closed' },
      pending: { bg: '#ffd700', icon: FiClock, text: 'Pending' },
    };
    return styles[status] || styles.active;
  };

  return (
    <div className="panel">
      <div className="panel-title">Jobs Panel</div>
      
      {/* Summary Stats */}
      <div style={{ display: 'flex', gap: 12, marginBottom: 16, flexWrap: 'nowrap', overflow: 'auto' }}>
        <div style={{ flex: 1, padding: '6px 12px', background: 'rgba(0, 217, 115, 0.1)', border: '0.5px solid rgba(0, 217, 115, 0.3)', borderRadius: 4, textAlign: 'center' }}>
          <div style={{ fontSize: 8, color: '#8696a0', marginBottom: 1 }}>Total Jobs</div>
          <div style={{ fontSize: 14, fontWeight: 'bold', color: '#00d973' }}>{jobs.length}</div>
        </div>
        <div style={{ flex: 1, padding: '6px 12px', background: 'rgba(0, 217, 115, 0.1)', border: '0.5px solid rgba(0, 217, 115, 0.3)', borderRadius: 4, textAlign: 'center' }}>
          <div style={{ fontSize: 8, color: '#8696a0', marginBottom: 1 }}>Active Jobs</div>
          <div style={{ fontSize: 14, fontWeight: 'bold', color: '#00d973' }}>{jobs.filter(j => j.status === 'active').length}</div>
        </div>
        <div style={{ flex: 1, padding: '6px 12px', background: 'rgba(255, 215, 0, 0.1)', border: '0.5px solid rgba(255, 215, 0, 0.3)', borderRadius: 4, textAlign: 'center' }}>
          <div style={{ fontSize: 8, color: '#8696a0', marginBottom: 1 }}>Pending Jobs</div>
          <div style={{ fontSize: 14, fontWeight: 'bold', color: '#ffd700' }}>{jobs.filter(j => j.status === 'pending').length}</div>
        </div>
        <div style={{ flex: 1, padding: '6px 12px', background: 'rgba(255, 107, 107, 0.1)', border: '0.5px solid rgba(255, 107, 107, 0.3)', borderRadius: 4, textAlign: 'center' }}>
          <div style={{ fontSize: 8, color: '#8696a0', marginBottom: 1 }}>Closed Jobs</div>
          <div style={{ fontSize: 14, fontWeight: 'bold', color: '#ff6b6b' }}>{jobs.filter(j => j.status === 'closed').length}</div>
        </div>
      </div>

      {/* Filters */}
      <div style={{ display: 'flex', gap: 8, marginBottom: 12, flexWrap: 'nowrap', alignItems: 'center' }}>
        <div style={{ flex: 1, minWidth: 150, position: 'relative' }}>
          <FiSearch style={{ position: 'absolute', left: 8, top: '50%', transform: 'translateY(-50%)', color: '#8696a0' }} />
          <input
            type="text"
            placeholder="Search jobs or companies..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="input"
            style={{ 
              paddingLeft: 32, 
              width: '100%', 
              backgroundColor: 'black', 
              color: 'white', 
              fontSize: '13px',
              border: '1px solid transparent',
              borderRadius: '4px',
              transition: 'border-color 0.2s',
              outline: 'none'
            }}
          />
        </div>
        <select
          className="select"
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          style={{ flex: 0.5, minWidth: 60, fontSize: '10px' }}
        >
          <option value="all">All Status</option>
          <option value="active">Active</option>
          <option value="pending">Pending</option>
          <option value="closed">Closed</option>
        </select>
      </div>

      {/* Jobs Grid */}
      <div style={{ overflowX: 'auto', border: '0.5px solid #2a3942', borderRadius: '4px' }}>
        <table className="table">
          <thead>
            <tr>
              <th style={{ width: '5%', textAlign: 'center' }}>#</th>
              <th style={{ width: '15%' }}>Title</th>
              <th style={{ width: '12%' }}>Company</th>
              <th style={{ width: '10%' }}>Salary</th>
              <th style={{ width: '10%', textAlign: 'center' }}>Applications</th>
              <th style={{ width: '10%', textAlign: 'center' }}>Views</th>
              <th style={{ width: '12%', textAlign: 'center' }}>Status</th>
              <th style={{ width: '12%', textAlign: 'center' }}>Posted</th>
              <th style={{ width: '12%', textAlign: 'center' }}>Action</th>
            </tr>
          </thead>
          <tbody>
            {filteredJobs.map((job, idx) => {
              const statusBadge = getStatusBadge(job.status);
              const StatusIcon = statusBadge.icon;
              return (
                <tr key={job.id}>
                  <td style={{ width: '5%', textAlign: 'center' }}>{idx + 1}</td>
                  <td style={{ width: '15%' }}>{job.title}</td>
                  <td style={{ width: '12%' }}>{job.company}</td>
                  <td style={{ width: '10%' }}>{job.salary}</td>
                  <td style={{ width: '10%', textAlign: 'center' }}>{job.applications}</td>
                  <td style={{ width: '10%', textAlign: 'center' }}>{job.views}</td>
                  <td style={{ width: '12%', textAlign: 'center' }}>
                    <span className="badge" style={{ color: statusBadge.bg, display: 'inline-flex', alignItems: 'center', gap: 4, padding: '4px 8px', borderRadius: 4, fontSize: 11, textTransform: 'none', border: 'none' }}>
                      {statusBadge.text}
                    </span>
                  </td>
                  <td style={{ width: '12%', textAlign: 'center' }}>{job.posted}</td>
                  <td style={{ width: '12%', textAlign: 'center', verticalAlign: 'middle' }}>
                    <button
                      className="btn"
                      style={{ 
                        padding: '4px 8px', 
                        fontSize: '12px', 
                        whiteSpace: 'nowrap', 
                        border: 'none',
                        borderRadius: '4px',
                        backgroundColor: 'transparent',
                        color: '#00d973',
                        fontWeight: '600',
                        cursor: 'pointer',
                        transition: 'all 0.2s ease'
                      }}
                    >
                      Details
                    </button>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      {/* Pagination Info */}
      <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', marginTop: 16, paddingTop: 12, borderTop: '1px solid rgba(134, 150, 160, 0.2)' }}>
        <div style={{ fontSize: 12, color: '#8696a0' }}>
          {filteredJobs.length} of {jobs.length} jobs
        </div>
      </div>
    </div>
  );
};

export default JobsManagement;
